mapper.select:
SELECT d.dev_id,d.dev_nm,d.mng_no,coalesce(d.main_job_cd,'') AS job_cd,d.grd_cd,d.rsgn_dt
FROM mst.dev d WHERE d.use_yn='Y' AND (d.hire_dt IS NULL OR d.hire_dt<=#{end})
AND d.main_job_cd=#{job}
AND d.grd_cd=#{grade}
AND EXISTS(SELECT 1 FROM mst.dev_skl s WHERE s.dev_id=d.dev_id AND s.skl_cd=#{skill})
AND d.emp_se_cd=#{emp_se_cd}
ORDER BY d.dev_id
